import Foundation

// MARK: - MTA bus (stop catalog)
//
// Data is generated by tools/generate_bus.py from MTA's official static bus GTFS (Resources/bus_stops.json):
// each bus stop's ID, name and coordinates, plus the routes and directions through it; each route's color, both directions' terminals and service type.
// Bus stop IDs are all digits (e.g. 550559), so they never collide with subway station IDs (e.g. 712, A24).

/// Bus service type (MTA official categories).
public enum BusService: String, Codable, Sendable, CaseIterable {
    /// Regular bus, stops at every stop
    case local
    /// Limited-Stop: stops at only some stops (some trips on the same route)
    case limited
    /// Select Bus Service (SBS): pay before boarding, fewer stops, route number followed by "+"
    case selectBus
    /// Express: express bus (starting with X, BxM, BM, QM, SIM), higher fare
    case express
}

public struct BusCatalog: Sendable {

    public struct Route: Codable, Hashable, Sendable {
        /// Display name, e.g. "Q53-SBS"
        public var name: String
        /// Hex color
        public var color: String
        /// Whether it's express (SBS or Express bus)
        public var express: Bool
        /// Operator: MTA NYCT or MTABC
        public var agency: String
        /// Terminals of the two directions ("0", "1")
        public var headsigns: [String: String]
    }

    public struct Stop: Sendable, Hashable {
        public var id: String
        public var name: String
        public var lat: Double
        public var lon: Double
        /// Routes and directions through this stop, e.g. ("Q18", "0")
        public var routeDirections: [RouteDirection]
        public var coordinate: Coordinate { Coordinate(latitude: lat, longitude: lon) }
    }

    public struct RouteDirection: Sendable, Hashable {
        public var route: String
        public var direction: String
    }

    public let feedVersion: String
    public let routes: [String: Route]
    public let stops: [Stop]
    private let byID: [String: Stop]

    public init(feedVersion: String, routes: [String: Route], stops: [Stop]) {
        self.feedVersion = feedVersion
        self.routes = routes
        self.stops = stops
        var map: [String: Stop] = [:]
        for s in stops { map[s.id] = s }
        byID = map
    }

    private struct Document: Decodable {
        var feedVersion: String?
        var routes: [String: Route]
        var stops: [[StopField]]
    }

    private enum StopField: Decodable {
        case string(String)
        case number(Double)
        case list([String])

        init(from decoder: Decoder) throws {
            let c = try decoder.singleValueContainer()
            if let s = try? c.decode(String.self) { self = .string(s) }
            else if let d = try? c.decode(Double.self) { self = .number(d) }
            else { self = .list(try c.decode([String].self)) }
        }
    }

    public static func decode(_ data: Data) throws -> BusCatalog {
        let doc = try JSONDecoder().decode(Document.self, from: data)
        var stops: [Stop] = []
        stops.reserveCapacity(doc.stops.count)
        for row in doc.stops {
            guard row.count >= 5,
                  case let .string(id) = row[0], case let .string(name) = row[1],
                  case let .number(lat) = row[2], case let .number(lon) = row[3],
                  case let .list(rds) = row[4] else { continue }
            let pairs = rds.compactMap { s -> RouteDirection? in
                let parts = s.split(separator: "|", maxSplits: 1).map(String.init)
                return parts.count == 2 ? RouteDirection(route: parts[0], direction: parts[1]) : nil
            }
            stops.append(Stop(id: id, name: name, lat: lat, lon: lon, routeDirections: pairs))
        }
        return BusCatalog(feedVersion: doc.feedVersion ?? "", routes: doc.routes, stops: stops)
    }

    public static func loadBundled() throws -> BusCatalog {
        guard let url = Bundle.module.url(forResource: "bus_stops", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try decode(Data(contentsOf: url))
    }

    public func stop(id: String) -> Stop? { byID[id] }

    /// Routes through this stop (unique, sorted by route name).
    public func routes(atStop id: String) -> [String] {
        var seen = Set<String>()
        return (byID[id]?.routeDirections ?? []).map(\.route).filter { seen.insert($0).inserted }.sorted(by: Self.routeOrder)
    }

    /// Route sorting: by letter prefix first, then by number (B1, B2, B11 ...).
    public static func routeOrder(_ a: String, _ b: String) -> Bool {
        func split(_ s: String) -> (String, Int, String) {
            let prefix = s.prefix { $0.isLetter }
            let rest = s.dropFirst(prefix.count)
            let digits = rest.prefix { $0.isNumber }
            return (String(prefix), Int(digits) ?? 0, String(rest.dropFirst(digits.count)))
        }
        let x = split(a), y = split(b)
        if x.0 != y.0 { return x.0 < y.0 }
        if x.1 != y.1 { return x.1 < y.1 }
        return x.2 < y.2
    }

    // MARK: Nearby bus stops

    /// Bus stops within walking range, organized into `Station`s like the subway:
    /// - keep only the nearest stop for each direction of each route (stops follow one another along the same street, so the nearest is enough);
    /// - stops with the same name within 250 m (usually on either side of an intersection) merge into one "station group", shown with two directions like a subway station;
    /// - at most `limit` stops, sorted by distance;
    /// - with `include`, only stops it takes (Demo mode: the ones in its area), before any of this is picked.
    public func stations(near coordinate: Coordinate, radiusMeters: Double, limit: Int = 30,
                         where include: ((Coordinate) -> Bool)? = nil) -> [Station] {
        let candidates = stops
            .map { ($0, WalkEstimator.distanceMeters(coordinate, $0.coordinate)) }
            .filter { $0.1 <= radiusMeters && include?($0.0.coordinate) != false }
            .sorted { $0.1 < $1.1 }
        var nearestFor: Set<RouteDirection> = []
        var chosen: [Stop] = []
        for (stop, _) in candidates {
            let fresh = stop.routeDirections.filter { !nearestFor.contains($0) }
            guard !fresh.isEmpty else { continue }
            fresh.forEach { nearestFor.insert($0) }
            chosen.append(stop)
            if chosen.count >= limit { break }
        }
        let groups = Self.groupKeys(chosen)
        return chosen.map { stop in
            Station(id: stop.id, name: stop.name, coordinate: stop.coordinate, entrances: [],
                    entranceToPlatformSeconds: 0, complexID: groups[stop.id])
        }
    }

    /// Group stops with the same name within 250 m; returns stop ID → group ID ("bus:" + the smallest stop ID in the group).
    static func groupKeys(_ stops: [Stop]) -> [String: String] {
        var result: [String: String] = [:]
        var groups: [[Stop]] = []
        for stop in stops {
            if let i = groups.firstIndex(where: { g in
                g[0].name == stop.name && g.allSatisfy { WalkEstimator.distanceMeters($0.coordinate, stop.coordinate) <= 250 }
            }) {
                groups[i].append(stop)
            } else {
                groups.append([stop])
            }
        }
        for g in groups {
            let key = "bus:" + (g.map(\.id).min() ?? g[0].id)
            for s in g { result[s.id] = key }
        }
        return result
    }

    // MARK: Direction

    /// Which side a stop is on within its group: the stop with the smallest ID in the group is "N";
    /// other stops are also "N" if they share a route and direction with it, otherwise "S" (the other side of the intersection).
    /// In the UI "N"/"S" only split into two columns; titles use terminals (e.g. "To Jamaica").
    public func side(ofStop id: String, among groupStopIDs: [String]) -> String {
        guard let first = groupStopIDs.min(), id != first,
              let a = byID[first], let b = byID[id] else { return "N" }
        return Set(a.routeDirections).isDisjoint(with: b.routeDirections) ? "S" : "N"
    }

    /// A route's terminal in one direction (the most common wording in the timetable).
    public func headsign(route: String, direction: String) -> String? {
        routes[route]?.headsigns[direction]
    }

    /// Normalizes terminal names from live data (all caps, possibly with "LTD", "SELECT BUS") to match the static data.
    public static func cleanDestination(_ raw: String) -> String {
        var s = raw.trimmingCharacters(in: .whitespaces)
        for prefix in ["+", "SELECT BUS ", "LIMITED ", "LTD ", "EXPRESS "] where s.uppercased().hasPrefix(prefix) {
            s = String(s.dropFirst(prefix.count)).trimmingCharacters(in: .whitespaces)
        }
        if let r = s.range(of: " via ", options: .caseInsensitive) { s = String(s[..<r.lowerBound]) }
        return niceName(s)
    }

    /// "WILLIS AV/E 138 ST" → "Willis Av / E 138 St" (same as nice() in tools/generate_bus.py).
    public static func niceName(_ raw: String) -> String {
        let keepUpper: Set<String> = ["SBS", "JFK", "LIRR", "CUNY", "NYC", "MTA", "US", "VA", "LGA", "PATH", "II", "III", "IV", "SI", "UPS"]
        let small: Set<String> = ["of", "and", "via", "to", "the", "at"]
        let spaced = raw.replacingOccurrences(of: #"\s*/\s*"#, with: " / ", options: .regularExpression)
        let words = spaced.split(separator: " ").enumerated().map { i, w -> String in
            let word = String(w)
            if keepUpper.contains(word.uppercased()) { return word.uppercased() }
            if word.range(of: #"^\d+(ST|ND|RD|TH)$"#, options: [.regularExpression, .caseInsensitive]) != nil {
                return word.lowercased()
            }
            if i > 0, small.contains(word.lowercased()) { return word.lowercased() }
            return word.split(separator: "-", omittingEmptySubsequences: false)
                .map { $0.prefix(1).uppercased() + $0.dropFirst().lowercased() }
                .joined(separator: "-")
        }
        return words.joined(separator: " ")
    }

    // MARK: Service type

    /// A route's own service type: a route number with "+" is SBS; starting with X, BxM, BM, QM, SIM is Express; otherwise regular bus.
    public static func service(ofRoute route: String) -> BusService {
        let r = route.uppercased()
        if r.hasSuffix("+") || r.contains("SBS") { return .selectBus }
        if r.range(of: #"^(BXM|BM|QM|SIM|X)\d"#, options: .regularExpression) != nil { return .express }
        return .local
    }

    /// A trip's service type: on a regular route, trips whose terminal says "LTD"/"LIMITED" are Limited-Stop.
    public static func service(route: String, destination: String?) -> BusService {
        let base = service(ofRoute: route)
        guard base == .local, let d = destination?.uppercased() else { return base }
        return d.hasPrefix("LTD ") || d.hasPrefix("LIMITED ") ? .limited : .local
    }

    /// Whether it's a bus route (subway routes are a fixed set of one or two characters, e.g. 7, A, GS, SI).
    public static func isBusRoute(_ route: String) -> Bool {
        let subway: Set<String> = ["1", "2", "3", "4", "5", "6", "7", "6X", "7X", "FX", "A", "B", "C", "D", "E", "F",
                                   "G", "J", "L", "M", "N", "Q", "R", "W", "Z", "S", "GS", "FS", "H", "SI", "SIR"]
        return !subway.contains(route)
    }
}
